func (c *Checker) initializeChecker() {
	var ambientModuleSymbols []*ast.Symbol
	augmentations := make([][]ast.Handle, 0, len(c.files))
	for _, file := range c.files {
		if !ast.IsExternalOrCommonJSModule(file) {
			if fileGlobalThisSymbol := file.BoundLocals()["globalThis"]; fileGlobalThisSymbol != nil {
				for _, d := range ast.DeclarationNodes(fileGlobalThisSymbol) {
					c.addDiagnostic(NewDiagnosticForNode(d, diagnostics.Declaration_name_conflicts_with_built_in_global_identifier_0, "globalThis"))
				}
			}
			for _, symbol := range file.BoundLocals() {
				if symbol.Flags&ast.SymbolFlagsModule != 0 && ast.IsAmbientModuleSymbolName(symbol.Name) {
					ambientModuleSymbols = append(ambientModuleSymbols, symbol)
				} else {
					c.mergeGlobalSymbol(symbol)
				}
			}
		}
		c.patternAmbientModules = append(c.patternAmbientModules, file.PatternAmbientModules...)
		augmentations = append(augmentations, file.ModuleAugmentations)
		if file.Symbol != nil {
			for name, symbol := range file.GlobalExports {
				if _, ok := c.globals[name]; !ok {
					c.globals[name] = symbol
				}
			}
		}
	}
	for _, list := range augmentations {
		for _, augmentation := range list {
			if ast.IsGlobalScopeAugmentation(augmentation.Parent()) {
				c.mergeModuleAugmentation(augmentation)
			}
		}
	}
	c.addUndefinedToGlobalsOrErrorOnRedeclaration()
	c.valueSymbolLinks.Get(c.undefinedSymbol).resolvedType = c.undefinedWideningType
	c.valueSymbolLinks.Get(c.argumentsSymbol).resolvedType = c.getGlobalType("IArguments", 0, true)
	c.valueSymbolLinks.Get(c.unknownSymbol).resolvedType = c.errorType
	c.valueSymbolLinks.Get(c.globalThisSymbol).resolvedType = c.newObjectType(ObjectFlagsAnonymous, c.globalThisSymbol)
	c.globalArrayType = c.getGlobalType("Array", 1, true)
	c.globalObjectType = c.getGlobalType("Object", 0, true)
	c.globalFunctionType = c.getGlobalType("Function", 0, true)
	c.globalCallableFunctionType = c.getGlobalStrictFunctionType("CallableFunction")
	c.globalNewableFunctionType = c.getGlobalStrictFunctionType("NewableFunction")
	c.globalStringType = c.getGlobalType("String", 0, true)
	c.globalNumberType = c.getGlobalType("Number", 0, true)
	c.globalBooleanType = c.getGlobalType("Boolean", 0, true)
	c.globalRegExpType = c.getGlobalType("RegExp", 0, true)
	c.anyArrayType = c.createArrayType(c.anyType)
	c.autoArrayType = c.createArrayType(c.autoType)
	if c.autoArrayType == c.emptyObjectType {
		c.autoArrayType = c.newAnonymousType(nil, nil, nil, nil, nil)
	}
	c.globalReadonlyArrayType = c.getGlobalType("ReadonlyArray", 1, false)
	if c.globalReadonlyArrayType == c.emptyGenericType {
		c.globalReadonlyArrayType = c.globalArrayType
	}
	c.anyReadonlyArrayType = c.createTypeFromGenericGlobalType(c.globalReadonlyArrayType, []*Type{c.anyType})
	c.globalThisType = c.getGlobalType("ThisType", 1, false)
	for _, symbol := range ambientModuleSymbols {
		c.mergeGlobalSymbol(symbol)
	}
	for _, list := range augmentations {
		for _, augmentation := range list {
			if !ast.IsGlobalScopeAugmentation(augmentation.Parent()) {
				c.mergeModuleAugmentation(augmentation)
			}
		}
	}
}
func (c *Checker) mergeGlobalSymbol(symbol *ast.Symbol) {
	globalSymbol := c.globals[symbol.Name]
	var merged *ast.Symbol
	if globalSymbol != nil {
		merged = c.mergeSymbol(globalSymbol, symbol, false)
	} else {
		merged = c.getMergedSymbol(symbol)
	}
	c.globals[symbol.Name] = merged
}
func (c *Checker) mergeModuleAugmentation(moduleName ast.Handle) {
	moduleNode := moduleName.Parent()
	moduleAugmentation := moduleNode
	if ast.NodeOf(moduleAugmentation.Symbol().Declarations[0]) != moduleNode {
		return
	}
	if ast.IsGlobalScopeAugmentation(moduleNode) {
		c.mergeSymbolTable(c.globals, moduleAugmentation.Symbol().Exports, false, nil)
	} else {
		var moduleNotFoundError *diagnostics.Message
		if moduleName.Parent().Parent().Flags()&ast.NodeFlagsAmbient == 0 {
			moduleNotFoundError = diagnostics.Invalid_module_name_in_augmentation_module_0_cannot_be_found
		}
		mainModule := c.resolveExternalModuleNameWorker(moduleName, moduleName, moduleNotFoundError, false, true)
		if mainModule == nil {
			return
		}
		mainModule = c.resolveExternalModuleSymbol(mainModule, false)
		if mainModule.Flags&ast.SymbolFlagsNamespace != 0 {
			if core.Some(c.patternAmbientModules, func(module *ast.PatternAmbientModule) bool {
				return mainModule == module.Symbol
			}) {
				merged := c.mergeSymbol(moduleAugmentation.Symbol(), mainModule, true)
				ast.GetSymbolTable(&c.patternAmbientModuleAugmentations)[moduleName.Text()] = merged
			} else {
				if mainModule.Exports[ast.InternalSymbolNameExportStar] != nil && len(moduleAugmentation.Symbol().Exports) != 0 {
					resolvedExports := c.getResolvedMembersOrExportsOfSymbol(mainModule, MembersOrExportsResolutionKindResolvedExports)
					for key, value := range moduleAugmentation.Symbol().Exports {
						if resolvedExports[key] != nil && mainModule.Exports[key] == nil {
							c.mergeSymbol(resolvedExports[key], value, false)
						}
					}
				}
				c.mergeSymbol(mainModule, moduleAugmentation.Symbol(), false)
			}
		} else {
			c.error(moduleName, diagnostics.Cannot_augment_module_0_because_it_resolves_to_a_non_module_entity, moduleName.Text())
		}
	}
}
func (c *Checker) addUndefinedToGlobalsOrErrorOnRedeclaration() {
	name := c.undefinedSymbol.Name
	targetSymbol := c.globals[name]
	if targetSymbol != nil {
		for _, declaration := range ast.DeclarationNodes(targetSymbol) {
			if !ast.IsTypeDeclaration(declaration) {
				c.addDiagnostic(createDiagnosticForNode(declaration, diagnostics.Declaration_name_conflicts_with_built_in_global_identifier_0, name))
			}
		}
	} else {
		c.globals[name] = c.undefinedSymbol
	}
}
